<?php
declare(strict_types=1);
namespace App\Interface\Http\Catalog;
use App\Application\Catalog\DTO\Request\CreateTagRequestDto;use App\Application\Catalog\Mapper\TagResponseMapper;use App\Application\Catalog\Service\CreateTagService;use App\Application\Catalog\Service\ListTagsService;use App\Application\Identity\Service\AuthService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use App\Infrastructure\Persistence\Doctrine\DoctrineEntityManagerFactory;use App\Infrastructure\Persistence\Doctrine\DoctrineTransactionManager;use App\Infrastructure\Persistence\Doctrine\Catalog\DoctrineTagRepository;use App\Interface\Http\Identity\IdentityRequestFactory;use DomainException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;use Slim\App;
final class TagRouteRegistrar {public function __construct(private readonly ApiResponseFactory $responses,private readonly AuthService $auth){}public function register(App $app):void{$em=DoctrineEntityManagerFactory::create();$repo=new DoctrineTagRepository($em);$create=new CreateTagService($repo,new TagResponseMapper(),new DoctrineTransactionManager($em));$list=new ListTagsService($repo,new TagResponseMapper());$identity=new IdentityRequestFactory();$responses=$this->responses;$auth=$this->auth;$app->get('/v1/tags',static function(ServerRequestInterface $r,ResponseInterface $p)use($identity,$auth,$list,$responses):ResponseInterface{try{$auth->currentUser($identity->accessToken($r));return $responses->success($p,$list->list(),(string)$r->getAttribute('request_id'));}catch(DomainException|UnavailableUserException|\InvalidArgumentException){return $responses->problem($p,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$r->getAttribute('request_id'));}});}}
